#!/usr/bin/env bash
# Generates local-only credentials for the development stack. Never commit the output.
set -euo pipefail
cd "$(dirname "$0")"

if [[ ! -f .env ]]; then
  gen() { openssl rand -hex 24; }
  cat > .env <<ENV
# Generated by init-env.sh on $(date -u +%Y-%m-%dT%H:%M:%SZ). Local development only. Do not commit.
POSTGRES_PASSWORD=$(gen)
REDIS_PASSWORD=$(gen)
RABBITMQ_PASSWORD=$(gen)
KEYCLOAK_ADMIN_PASSWORD=$(gen)
S3_ACCESS_KEY=intima-local-$(openssl rand -hex 4)
S3_SECRET_KEY=$(gen)
ENV
  chmod 600 .env
  echo "Created infrastructure/docker/.env"
fi

# shellcheck disable=SC1091
source .env
mkdir -p .generated
cat > .generated/s3.json <<JSON
{
  "identities": [
    {
      "name": "intima-local",
      "credentials": [{ "accessKey": "${S3_ACCESS_KEY}", "secretKey": "${S3_SECRET_KEY}" }],
      "actions": ["Admin", "Read", "Write", "List", "Tagging"]
    }
  ]
}
JSON
chmod 644 .generated/s3.json
